impl Drop for WizardWindowInner {
    fn drop(&mut self) {
        self.base.closed();
    }
}

impl slint::StrongHandle for WizardWindow {
    type WeakInner = std::rc::Weak<WizardWindowInner>;
    fn upgrade_from_weak_inner(inner: &Self::WeakInner) -> Option<Self> {
        inner.upgrade().map(Self)
    }
}
impl slint::ComponentHandle for WizardWindow {
    fn as_weak(&self) -> slint::Weak<Self> {
        slint::Weak::new(Rc::downgrade(&self.0))
    }
    fn clone_strong(&self) -> Self {
        Self(self.0.clone())
    }
    fn show(&self) -> Result<(), slint::PlatformError> {
        self.0.base.show()
    }
    fn hide(&self) -> Result<(), slint::PlatformError> {
        self.0.base.hide()
    }
    fn window(&self) -> &slint::Window {
        self.0.base.window()
    }
    fn run(&self) -> Result<(), slint::PlatformError> {
        self.show()?;
        slint::run_event_loop()?;
        self.hide()
    }
    fn global<'a, T: slint::Global<'a, Self>>(&'a self) -> T {
        T::get(self)
    }
}

